// Command aggregate-write is a fully offline, self-contained example of how a
// caller tells a successful aggregation run apart from a WRITE-side failure:
// records come from an in-memory io.Reader (strings.Reader) and window results
// and late-event notices go into in-memory io.Writer implementations. Nothing
// touches the network, files or the current time.
//
// It feeds the SAME 1000 ms fixed-window input to edgefleet.RunAggregate four
// times:
//
//  1. control: the result writer is a plain bytes.Buffer. The final watermark
//     closes three windows at once and all three result lines come back.
//  2. writer accepts the whole result line (JSON + newline) and THEN returns
//     its own error: the run still fails with *edgefleet.OutputError; the full
//     byte count never cancels the error.
//  3. writer accepts only a prefix and returns nil: io.ErrShortWrite marks the
//     line incomplete.
//  4. writer accepts only a prefix and returns its own error: that original
//     error is kept and errors.Is reaches it through *edgefleet.OutputError.
//
// In every failing case the caller can see exactly what the writer already
// held: earlier fully written result lines are valid window results; the
// failed line's accepted prefix is a residual fragment, NOT a valid window
// result. The engine neither retries/resends the failed content nor emits the
// other windows that same watermark had also closed, reads no further records,
// and end of input never flushes still-open windows.
//
// Run it offline with:
//
//	go run ./examples/aggregate-write
package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
)

// errSinkBroken stands in for the failure a real result destination (a broken
// network connection, a quota-exhausted log pipeline, a vanished pipe) reports
// after accepting some bytes. The run returns it inside *edgefleet.OutputError
// so errors.Is keeps working for the caller.
var errSinkBroken = errors.New("result sink connection broken")

// sharedInput is the one input every scenario uses, line-delimited JSON,
// 1000 ms fixed windows, one key sensor-a, 7 physical lines. A blank line
// consumes physical line 3 so the error's Line field maps 1:1 to the input
// shown below; blank records are ignored but keep their line number.
//
//	line 1: event time=100  value=1  -> [0,1000)
//	line 2: event time=150  value=2  -> [0,1000)
//	line 3: (blank)
//	line 4: event time=1100 value=3  -> [1000,2000)
//	5th physical: event time=2100 value=4 -> [2000,3000)
//	line 6: watermark 3000 -> closes [0,1000), [1000,2000), [2000,3000) at once
//	line 7: event time=3100 value=5 -> [3000,4000), never closed (no later watermark)
const sharedInput = "" +
	`{"type":"event","key":"sensor-a","time":100,"value":1}` + "\n" +
	`{"type":"event","key":"sensor-a","time":150,"value":2}` + "\n" +
	`` + "\n" +
	`{"type":"event","key":"sensor-a","time":1100,"value":3}` + "\n" +
	`{"type":"event","key":"sensor-a","time":2100,"value":4}` + "\n" +
	`{"type":"watermark","time":3000}` + "\n" +
	`{"type":"event","key":"sensor-a","time":3100,"value":5}`

// failurePolicy describes how a scriptedWriter should behave on its second
// Write call — the one carrying the MIDDLE of the three windows the line-6
// watermark closes in one batch.
type failurePolicy struct {
	accept int   // bytes of that write it keeps
	err    error // what it returns on that write
}

// scriptedWriter is an io.Writer that buffers every accepted byte while
// scripted to fail exactly once: on the writeAttempt for which failAtCall is
// set (2 = the middle result line) it keeps `accept` bytes of that one write
// and returns (accept, err); every other write is accepted in full. Counting
// calls rather than matching content makes the trigger deterministic without
// relying on output ordering guarantees beyond the documented order (by end
// ascending, then key).
type scriptedWriter struct {
	got       bytes.Buffer
	call      int
	failAtCall int
	policy    failurePolicy
}

func (w *scriptedWriter) Write(p []byte) (int, error) {
	w.call++
	if w.call == w.failAtCall {
		k := w.policy.accept
		if k > len(p) {
			k = len(p)
		}
		if k > 0 {
			w.got.Write(p[:k])
		}
		return k, w.policy.err
	}
	return w.got.Write(p)
}

// fullLineThenErrorWriter accepts EVERY byte of the target write (the whole
// JSON line including its trailing newline) and returns its own error
// anyway — a sink that received the complete line but still reported the
// delivery failed. Receiving all bytes must not cancel the error.
type fullLineThenErrorWriter struct {
	got       bytes.Buffer
	call      int
	failAtCall int
	err       error
}

func (w *fullLineThenErrorWriter) Write(p []byte) (int, error) {
	w.call++
	if w.call == w.failAtCall {
		w.got.Write(p) // keep all len(p) bytes, including the newline
		return len(p), w.err
	}
	return w.got.Write(p)
}

// lineBoundaryView splits a received byte stream into the complete
// newline-terminated rows and any trailing residual fragment. It lets the
// printed report distinguish valid window result lines from the prefix of a
// failed write that must never be treated as a result.
type lineBoundaryView struct {
	complete []string
	residual string
}

func splitReceived(data string) lineBoundaryView {
	idx := strings.LastIndexByte(data, '\n')
	if idx < 0 {
		return lineBoundaryView{residual: data}
	}
	rows := strings.Split(data[:idx], "\n")
	return lineBoundaryView{complete: rows, residual: data[idx+1:]}
}

func main() {
	fmt.Println("shared input (7 physical lines, all with a trailing newline):")
	printNumbered(sharedInput)
	fmt.Println()
	fmt.Println("window parameters: RunAggregate(r, windowMillis=1000, out, lateLog)")
	fmt.Println("line 6 watermark 3000 closes three windows in one batch, in end-ascending order:")
	fmt.Println("  [0,1000) [1000,2000) [2000,3000)   <- emitted on one Write-per-line sequence")
	fmt.Println("  [3000,4000) stays open; line 7 is never reached in the failing runs")
	fmt.Println()

	// 1. Control: everything writes.
	runWriteScenario(
		"1. control: a healthy bytes.Buffer writer",
		bytes.NewBuffer(nil),
	)

	// 2. Full line received, writer's own error nonetheless.
	runWriteScenario(
		"2. writer holds the whole line (JSON + newline) but returns its own error",
		&fullLineThenErrorWriter{failAtCall: 2, err: errSinkBroken},
	)

	// 3. Prefix received, nil error -> io.ErrShortWrite.
	runWriteScenario(
		"3. writer holds only a prefix and returns nil",
		&scriptedWriter{failAtCall: 2, policy: failurePolicy{accept: 12, err: nil}},
	)

	// 4. Prefix received and own error -> original error preserved.
	runWriteScenario(
		"4. writer holds a prefix and returns its own error",
		&scriptedWriter{failAtCall: 2, policy: failurePolicy{accept: 12, err: errSinkBroken}},
	)
}

// runWriteScenario runs one aggregation over a fresh strings.Reader of the
// shared input with in-memory writers, then prints exactly what the caller
// observed: complete result rows, a residual fragment, the late notice stream
// and the returned error with its structured classification.
func runWriteScenario(title string, out io.Writer) {
	var late bytes.Buffer
	err := edgefleet.RunAggregate(strings.NewReader(sharedInput), 1000, out, &late)

	received := receivedString(out)
	view := splitReceived(received)

	fmt.Println("=== " + title + " ===")
	fmt.Println("complete result lines the writer already holds (valid window results):")
	printRows(view.complete)
	fmt.Printf("residual fragment after the last newline (NOT a valid window result): %s\n", quoteOrNone(view.residual))
	fmt.Printf("late-event notice stream (lateLog): %s\n", emptyMarker(late.String()))
	fmt.Printf("returned error: %v\n", errString(err))

	if err == nil {
		fmt.Println("  err == nil -> run succeeded; every window the watermark closed was written")
		fmt.Println()
		return
	}

	var oe *edgefleet.OutputError
	if !errors.As(err, &oe) {
		fmt.Println("  errors.As(*edgefleet.OutputError) -> false (not an output write failure)")
		fmt.Println()
		return
	}
	fmt.Printf("  errors.As(*edgefleet.OutputError) -> true\n")
	fmt.Printf("    triggering input line : %d (blank line 3 kept its line number)\n", oe.Line)
	fmt.Printf("    result category (Kind): %q\n", oe.Kind)
	fmt.Printf("    record detail         : %s\n", oe.Detail)
	fmt.Printf("    writer error (Err)    : %v\n", oe.Err)
	fmt.Printf("  errors.Is(err, errSinkBroken) -> %v (writer's own error exposed through Unwrap)\n", errors.Is(err, errSinkBroken))
	fmt.Printf("  errors.Is(err, io.ErrShortWrite) -> %v\n", errors.Is(err, io.ErrShortWrite))
	fmt.Println()
}

// receivedString reads back whatever the in-memory writer accepted. The
// concrete types differ between the control (bytes.Buffer via io.Writer) and
// the scripted writers; each exposes the buffered content through this helper.
func receivedString(out io.Writer) string {
	switch w := out.(type) {
	case *bytes.Buffer:
		return w.String()
	case *scriptedWriter:
		return w.got.String()
	case *fullLineThenErrorWriter:
		return w.got.String()
	}
	return ""
}

// printNumbered prints content with 1-based physical line numbers. The shared
// input is fully newline-terminated except the last line, so line 7 is marked
// as having no trailing newline only for the final event.
func printNumbered(content string) {
	lines := strings.Split(content, "\n")
	terminated := strings.HasSuffix(content, "\n")
	last := len(lines) - 1
	if terminated {
		last--
	}
	for i := 0; i <= last; i++ {
		ending := `  + "\n"`
		if i == last && !terminated {
			ending = "  (no newline)"
		}
		fmt.Printf("  line %d: %s%s\n", i+1, lines[i], ending)
	}
}

func printRows(rows []string) {
	if len(rows) == 0 {
		fmt.Println("  (none)")
		return
	}
	for _, row := range rows {
		fmt.Println("  " + row)
	}
}

func quoteOrNone(s string) {
}

func emptyMarker(content string) string {
	if content == "" {
		return "(none)"
	}
	return "\n" + indent(strings.TrimRight(content, "\n"))
}

func indent(s string) string {
	var b strings.Builder
	for _, line := range strings.Split(s, "\n") {
		b.WriteString("  " + line + "\n")
	}
	return strings.TrimRight(b.String(), "\n")
}

func errString(err error) string {
	if err == nil {
		return "<nil>"
	}
	return err.Error()
}

